-- Greenfield Tool Library: Part 3 database for team-10
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS checkout;
DROP TABLE IF EXISTS certification;
DROP TABLE IF EXISTS tool;
DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS member;
DROP TABLE IF EXISTS category;
SET FOREIGN_KEY_CHECKS = 1;

-- Greenfield Tool Library: reference schema (instructor solution for Part 2, Task 1)
-- MySQL 8.0.16+ (CHECK constraints are ignored before 8.0.16)

CREATE TABLE category (
    category_id            INT           NOT NULL,
    name                   VARCHAR(50)   NOT NULL,
    daily_late_fee         DECIMAL(6,2)  NOT NULL,
    max_loan_days          INT           NOT NULL,
    requires_certification BOOLEAN       NOT NULL,
    PRIMARY KEY (category_id),
    UNIQUE (name),
    CHECK (daily_late_fee >= 0),
    CHECK (max_loan_days >= 1)
);

CREATE TABLE member (
    member_id   INT           NOT NULL,
    first_name  VARCHAR(50)   NOT NULL,
    last_name   VARCHAR(50)   NOT NULL,
    email       VARCHAR(100)  NOT NULL,
    zip         CHAR(5)       NOT NULL,
    join_date   DATE          NOT NULL,
    status      ENUM('active', 'suspended') NOT NULL,
    PRIMARY KEY (member_id),
    UNIQUE (email)
);

CREATE TABLE staff (
    staff_id    INT           NOT NULL,
    first_name  VARCHAR(50)   NOT NULL,
    last_name   VARCHAR(50)   NOT NULL,
    email       VARCHAR(100)  NOT NULL,
    PRIMARY KEY (staff_id),
    UNIQUE (email)
);

CREATE TABLE tool (
    tool_id         INT           NOT NULL,
    name            VARCHAR(100)  NOT NULL,
    brand           VARCHAR(50)   NOT NULL,
    category_id     INT           NOT NULL,
    purchase_date   DATE          NOT NULL,
    purchase_price  DECIMAL(8,2)  NOT NULL,
    tool_condition  ENUM('good', 'fair', 'needs_repair', 'retired') NOT NULL,
    PRIMARY KEY (tool_id),
    FOREIGN KEY (category_id) REFERENCES category (category_id),
    CHECK (purchase_price >= 0)
);

CREATE TABLE certification (
    member_id     INT   NOT NULL,
    category_id   INT   NOT NULL,
    certified_on  DATE  NOT NULL,
    PRIMARY KEY (member_id, category_id),
    FOREIGN KEY (member_id)   REFERENCES member (member_id),
    FOREIGN KEY (category_id) REFERENCES category (category_id)
);

CREATE TABLE checkout (
    checkout_id    INT           NOT NULL AUTO_INCREMENT,
    tool_id        INT           NOT NULL,
    member_id      INT           NOT NULL,
    staff_id       INT           NOT NULL,
    checkout_date  DATE          NOT NULL,
    due_date       DATE          NOT NULL,
    return_date    DATE          NULL,
    late_fee       DECIMAL(8,2)  NOT NULL DEFAULT 0.00,
    PRIMARY KEY (checkout_id),
    FOREIGN KEY (tool_id)   REFERENCES tool (tool_id),
    FOREIGN KEY (member_id) REFERENCES member (member_id),
    FOREIGN KEY (staff_id)  REFERENCES staff (staff_id),
    CHECK (due_date >= checkout_date),
    CHECK (return_date IS NULL OR return_date >= checkout_date),
    CHECK (late_fee >= 0)
);

